package com.scamshield.reporting; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/reports") public class ReportController { private final ReportService service; public ReportController(ReportService s){service=s;} public record Request(@NotBlank String phoneNumber,@NotBlank String claimedProvider,@NotBlank String attackType,String description,String reporterKey){} @PostMapping public Map<String,Object> create(@Valid @RequestBody Request r,@RequestHeader(value="X-Reporter-Key",required=false) String key){return service.create(r.phoneNumber(),r.claimedProvider(),r.attackType(),r.description(),key==null?r.reporterKey():key);} @GetMapping public Object recent(){return service.recent();} }
